drop table if exists resultados, aprovacoes, pdis, usuarios, jogos, alunos cascade;

create table alunos (
  id text primary key,
  nome text not null,
  hiperfoco text            -- id do tema (trem, aranha, aviao, dinossauro; os mesmos do hub); null = ainda não 
escolheu
);

create table usuarios (
  id text primary key,
  email text unique not null,
  senha text not null,
  nome text not null,
  perfil text not null check (perfil in ('escola', 'responsavel', 'crianca')),
  aluno_id text references alunos(id)
);

-- Catálogo de jogos. game_id segue GAME_IDS de src/core/contracts.js.
-- As habilidades de cada jogo são provisórias: combinar com quem faz os jogos.
create table jogos (
  id text primary key,
  nome text not null,
  descricao text not null,
  habilidades text[] not null
);

create table pdis (
  id bigint generated always as identity primary key,
  aluno_id text not null references alunos(id),
  arquivo text not null,
  itens jsonb not null,       -- [{ habilidade, nivel }]
  resumo_pais jsonb,          -- { topicos, porHabilidade, aviso } de pdi/src/processarPdi.js
  erro text,
  criado_em timestamptz not null default now()
);

create table aprovacoes (
  aluno_id text not null references alunos(id),
  jogo_id text not null references jogos(id),
  status text not null check (status in ('sugerido', 'aprovado', 'recusado')),
  atualizado_em timestamptz not null default now(),
  primary key (aluno_id, jogo_id)
);

-- Mesmo formato de createResult() em src/core/contracts.js.
create table resultados (
  id bigint generated always as identity primary key,
  aluno_id text not null references alunos(id),
  jogo_id text not null references jogos(id),
  status text not null check (status in ('completed', 'abandoned')),
  attempts int not null check (attempts >= 0),
  correct int not null check (correct >= 0 and correct <= attempts),
  hints int not null default 0 check (hints >= 0),
  criado_em timestamptz not null default now()
);

-- O site acessa o banco só pelo servidor, com a service role key.
-- RLS ligado sem políticas bloqueia o acesso direto com a chave pública.
alter table alunos enable row level security;
alter table usuarios enable row level security;
alter table jogos enable row level security;
alter table pdis enable row level security;
alter table aprovacoes enable row level security;
alter table resultados enable row level security;

insert into alunos (id, nome, hiperfoco) values ('ana', 'Ana', null);

insert into usuarios (id, email, senha, nome, perfil, aluno_id) values
  ('escola-1', 'escola@demo.com', 'demo', 'Escola Sol Nascente', 'escola', null),
  ('resp-1', 'familia@demo.com', 'demo', 'Família da Ana', 'responsavel', 'ana'),
  ('crianca-1', 'ana@demo.com', 'demo', 'Ana', 'crianca', 'ana');

-- Catálogo de jogos: fonte são os manifestos em hub/src/jogos/*/manifesto.js.
-- Depois de mudar um manifesto, rode `npm run sincronizar-jogos` em site/server.
insert into jogos (id, nome, descricao, habilidades) values
  ('memoria', 'Jogo da memória', 'Vire as cartas e encontre os pares de figuras.', array['reconhecer-emocoes']),
  ('sequencia', 'Complete a sequência', 'Olhe a fila de figuras e descubra qual vem depois.', array['resposta-social', 
'empatia']),
  ('chuva-emocoes', 'Chuva de emoções', 'Rostos caem do céu. Pegue só a emoção pedida!', array['reconhecer-emocoes']),
  ('cuidar-amigo', 'Cuidar do amigo', 'Um amigo está com um sentimento. Arraste o que ajuda!', array['empatia', 
'causa-efeito-social']),
  ('plataforma-amigo', 'Plataforma do amigo', 'Corra, pule e ajude os amigos que encontrar pelo caminho.', 
array['resposta-social', 'empatia']),
  ('quebra-cabeca', 'Quebra-cabeça', 'Toque numa peça e depois na casa dela para montar a imagem inteira.', 
array['relacao-parte-todo']);

// Catálogo do hub: fonte única dos jogos. Para adicionar um jogo, crie jogos/<id>/
// seguindo jogos/contrato.js e acrescente uma linha aqui.
import { validarManifesto } from './contrato.js'
import memoria from './memoria/manifesto.js'
import sequencia from './sequencia/manifesto.js'
import chuvaEmocoes from './chuva-emocoes/manifesto.js'
import cuidarAmigo from './cuidar-amigo/manifesto.js'
import plataformaAmigo from './plataforma-amigo/manifesto.js'
import quebraCabeca from './quebra-cabeca/manifesto.js'
import guerraTortas from './guerra-tortas/manifesto.js'

// `carregar` só baixa o código do jogo quando a criança abre ele.
export const JOGOS = [
  { ...memoria, carregar: () => import('./memoria/index.js') },
  { ...sequencia, carregar: () => import('./sequencia/index.js') },
  { ...chuvaEmocoes, carregar: () => import('./chuva-emocoes/index.js') },
  { ...cuidarAmigo, carregar: () => import('./cuidar-amigo/index.js') },
  { ...plataformaAmigo, carregar: () => import('./plataforma-amigo/index.js') },
  { ...quebraCabeca, carregar: () => import('./quebra-cabeca/index.js') },
  { ...guerraTortas, carregar: () => import('./guerra-tortas/index.js') },
]

JOGOS.forEach(validarManifesto)

export const jogoPorId = (id) => JOGOS.find((j) => j.id === id) ?? null

// Capas dos jogos no estilo "papel recortado", com o personagem e os itens do tema.
// Cada capa mostra a mecânica do jogo e faz um gesto curto quando a criança aponta
// para o cartão (CSS em estilo.css, "Capas dos jogos"). Jogo sem capa aqui usa a arte padrão.
import { useId } from 'react'
import { urlDoQuadro } from '@hub/compartilhado/arte/index.js'

// Cartão de papel centrado em (0, 0): sombra chapada, papel e contorno.
function Papel({ w, h, cor = 'var(--papel-creme)', raio = 10 }) {
  return (
    <>
      <rect x={-w / 2 + 4} y={-h / 2 + 4} width={w} height={h} rx={raio} fill="var(--contorno)" />
      <rect x={-w / 2} y={-h / 2} width={w} height={h} rx={raio} fill={cor} stroke="var(--contorno)" strokeWidth="3" />
    </>
  )
}

function Figura({ src, tamanho }) {
  return <image href={src} x={-tamanho / 2} y={-tamanho / 2} width={tamanho} height={tamanho} />
}

// Verso da carta da memória: cor do tema com um brilho de quatro pontas.
function Verso({ w, h }) {
  return (
    <>
      <Papel w={w} h={h} cor="var(--tema)" />
      <path d="M0 -14 Q3 -3 14 0 Q3 3 0 14 Q-3 3 -14 0 Q-3 -3 0 -14Z" fill="#fff" opacity="0.9" />
    </>
  )
}

// Memória: uma carta aberta, uma fechada e uma que vira mostrando o par.
function CapaMemoria({ tema }) {
  const w = 64
  const h = 84
  return (
    <svg className="capa-svg capa-memoria" viewBox="0 0 260 170" aria-hidden="true">
      <g transform="translate(62 86) rotate(-6)">
        <Papel w={w} h={h} />
        <Figura src={tema.personagem} tamanho={52} />
      </g>
      <g transform="translate(130 84) rotate(2)">
        <Verso w={w} h={h} />
      </g>
      <g transform="translate(198 86) rotate(7)">
        <g className="capa-frente">
          <Papel w={w} h={h} />
          <Figura src={tema.personagem} tamanho={52} />
        </g>
        <g className="capa-verso">
          <Verso w={w} h={h} />
        </g>
      </g>
    </svg>
  )
}

// Sequência: personagem, item, personagem e um "?" que vira o item certo.
function CapaSequencia({ tema }) {
  const item = tema.itens[1] ?? tema.itens[0]
  const lado = 48
  const xs = [36, 99, 162, 225]
  const fila = [tema.personagem, item.img, tema.personagem]
  return (
    <svg className="capa-svg capa-sequencia" viewBox="0 0 260 170" aria-hidden="true">
      {fila.map((src, i) => (
        <g key={i} transform={`translate(${xs[i]} 88)`}>
          <Papel w={lado} h={lado} />
          <Figura src={src} tamanho={38} />
        </g>
      ))}
      <g transform={`translate(${xs[3]} 88)`}>
        <g className="capa-resposta">
          <Papel w={lado} h={lado} />
          <Figura src={item.img} tamanho={38} />
        </g>
        <g className="capa-pergunta">
          <Papel w={lado} h={lado} cor="#fff" />
          <rect x={-lado / 2 + 5} y={-lado / 2 + 5} width={lado - 10} height={lado - 10} rx="7" fill="none" stroke="var(--contorno)" strokeWidth="2" strokeDasharray="5 4" />
          <text y="11" textAnchor="middle" fontFamily="var(--titulo)" fontWeight="700" fontSize="30" fill="var(--contorno)">?</text>
        </g>
      </g>
    </svg>
  )
}

// Arte do hub que aparece nas capas (rostos e amigo), calculada uma vez só.
const ARTE_CAPA = {
  feliz: urlDoQuadro('rosto_feliz'),
  triste: urlDoQuadro('rosto_triste'),
  surpreso: urlDoQuadro('rosto_surpreso'),
  amigo: urlDoQuadro('amigo_coelho'),
}
const CORACAO = 'M50 88 C10 60 6 30 26 22 C40 17 48 26 50 32 C52 26 60 17 74 22 C94 30 90 60 50 88Z'

// id seguro para clipPath (o useId traz caracteres que não servem em url(#...))
const useIdSvg = () => `capa${useId().replace(/[^a-zA-Z0-9]/g, '')}`

// Quebra-cabeça: o personagem num tabuleiro com uma peça fora, que encaixa no buraco.
function CapaQuebraCabeca({ tema }) {
  const id = useIdSvg()
  // peça de baixo à direita, com um encaixe redondo para cima
  const peca = 'M100 86 H117 C110 70 145 70 138 86 H155 V141 H100 Z'
  return (
    <svg className="capa-svg capa-quebra" viewBox="0 0 260 170" aria-hidden="true">
      <defs>
        <clipPath id={id}><path d={peca} /></clipPath>
      </defs>
      <g transform="rotate(-3 100 86)">
        <rect x="45" y="31" width="114" height="114" rx="10" fill="var(--contorno)" />
        <rect x="41" y="27" width="118" height="118" rx="10" fill="var(--papel-creme)" stroke="var(--contorno)" strokeWidth="3" />
